Voce e um avaliador de qualidade de respostas de atendimento ao cliente da
Cadencia. Avalie a RESPOSTA GERADA contra o CONTEXTO DE POLITICA (a fonte de
verdade) e os CRITERIOS abaixo. De uma nota de 0 a 10 para CADA criterio,
com uma justificativa de uma frase. NAO avalie tamanho nem estilo de escrita
fora do que os criterios pedem explicitamente -- comprimento nao e um criterio.

PERGUNTA DO CLIENTE: {{pergunta}}
CONTEXTO DE POLITICA (fonte de verdade): {{contexto_politica}}
RESPOSTA GERADA: {{resposta_gerada}}

CRITERIOS:
{{criterios_globais}}

Responda SOMENTE com JSON no formato:
{"criterios": {"<id_do_criterio>": {"nota": <0-10>, "justificativa": "<uma frase>"}}}

// SuiteAvaliacaoJuiz/Program.cs -- dispara o Bedrock Evaluation Job, espera a
// conclusao, le o relatorio no S3 e aplica o gate por criterio. Reaproveita o
// cliente Bedrock do L81 e a estrutura de teste do L82 (TesteRegressaoPrompt.cs)
// -- aqui o veredito vem de um segundo modelo, nao de uma regra de string.

using System.Text.Json;
using Amazon.Bedrock;
using Amazon.Bedrock.Model;

var caminhoPrompt = args.Length > 0 ? args[0] : "prompts/atendimento-politicas.txt";
var textoPrompt = await File.ReadAllTextAsync(caminhoPrompt);

using var bedrock = new AmazonBedrockClient();

// O job aponta para o golden set no S3 -- nao para o texto do prompt em si; o
// prompt do PR e resolvido pelo CodeBuild antes de disparar o job.
var job = await bedrock.CreateEvaluationJobAsync(new CreateEvaluationJobRequest
{
    JobName = $"cadencia-avaliacao-atendimento-{DateTime.UtcNow:yyyyMMddHHmmss}",
    RoleArn = "arn:aws:iam::111122223333:role/AvaliacaoAtendimentoRole",
    EvaluationConfig = MontarConfigLlmAsJudge(
        modeloAvaliado: "us.anthropic.claude-3-5-haiku-20241022-v1:0",
        modeloJuiz:     "us.anthropic.claude-3-5-sonnet-20241022-v2:0",
        promptJuiz:     await File.ReadAllTextAsync("prompts/juiz-atendimento-politicas.txt")),
    InferenceConfig = MontarInferenceConfig(textoPrompt),
    OutputDataConfig = new EvaluationOutputDataConfig
    {
        S3Uri = "s3://cadencia-lake/atendimento/avaliacao-juiz/resultados/",
    },
});

var status = await EsperarConclusaoAsync(bedrock, job.JobArn);
if (status != EvaluationJobStatus.Completed)
{
    // Falha do job vira reprovacao -- nunca omissao. E o requisito no 6 da
    // tabela de requisitos virando codigo.
    Console.WriteLine($"job de avaliacao terminou como {status} -- pipeline bloqueado");
    Environment.Exit(1);
}

var relatorio = await LerRelatorioDoS3Async(job.OutputDataConfig.S3Uri);
var (aprovado, motivos) = AplicarGatePorCriterio(relatorio, pisoPorCriterio: 6.0,
    toleranciaAbaixoDoPiso: 0.10);

foreach (var m in motivos) Console.WriteLine($"  {m}");
Console.WriteLine(aprovado ? "golden set: aprovado em todos os criterios"
                            : "golden set: reprovado -- ver criterios acima");
Environment.Exit(aprovado ? 0 : 1); // CodeBuild le este codigo de saida

# pipeline-avaliacao-juiz.tf -- novo estagio no MESMO CodePipeline do L82,
# especifico para o prompt do assistente de atendimento.

resource "aws_codebuild_project" "avaliar_com_juiz" {
  name         = "${var.projeto}-avaliar-atendimento-juiz"
  service_role = aws_iam_role.pipeline_avaliacao.arn

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/standard:7.0"
    type         = "LINUX_CONTAINER"
    environment_variable {
      name  = "GOLDEN_SET_S3_URI"
      value = "s3://${aws_s3_bucket.avaliacao_atendimento.bucket}/golden-set/"
    }
  }

  source { type = "CODEPIPELINE", buildspec = "buildspec-avaliacao.yml" }
  artifacts { type = "CODEPIPELINE" }
}

resource "aws_s3_bucket" "avaliacao_atendimento" {
  bucket = "${var.projeto}-avaliacao-atendimento-juiz"
}

resource "aws_kms_key" "avaliacao_atendimento" {
  description             = "Golden set e resultado de avaliacao por juiz -- L88"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

resource "aws_glue_catalog_database" "avaliacao_atendimento" {
  name = "${var.projeto}_avaliacao_atendimento"
}

resource "aws_glue_catalog_table" "resultados_avaliacao" {
  name          = "resultados_avaliacao_juiz"
  database_name = aws_glue_catalog_database.avaliacao_atendimento.name
  table_type    = "EXTERNAL_TABLE"
  parameters    = { classification = "json" }

  storage_descriptor {
    location      = "s3://${aws_s3_bucket.avaliacao_atendimento.bucket}/resultados/"
    input_format  = "org.apache.hadoop.mapred.TextInputFormat"
    output_format = "org.apache.hadoop.hive.ql.io.HiveIgnoreKeyTextOutputFormat"
    ser_de_info { serialization_library = "org.openx.data.jsonserde.JsonSerDe" }

    columns { name = "caso_id"                    type = "string" }
    columns { name = "modelo_gerador"              type = "string" }
    columns { name = "modelo_juiz"                 type = "string" }
    columns { name = "comprimento_resposta_chars"  type = "int" }
    columns { name = "criterios"                   type = "string" } # JSON aninhado
  }
}

resource "aws_athena_workgroup" "avaliacao_atendimento" {
  name = "${var.projeto}-avaliacao-atendimento"
  configuration {
    enforce_workgroup_configuration = true
    result_configuration {
      output_location = "s3://${aws_s3_bucket.avaliacao_atendimento.bucket}/resultados-athena/"
      encryption_configuration {
        encryption_option = "SSE_KMS"
        kms_key_arn       = aws_kms_key.avaliacao_atendimento.arn
      }
    }
  }
}

